@dataclass
class SpectrumRecord:
    label: str
    timestamp: str
    command: str
    frequency_hz: List[float]
    real_ohm: List[float]
    imag_ohm: List[float]
    temperature_c: Optional[float] = None
    force_counts: Optional[float] = None
    force_g: Optional[float] = None
    force_n: Optional[float] = None
    note: str = ""
    cole_fit: Dict[str, Any] = field(default_factory=dict)


class BLETransport:
    def __init__(
        self,
        loop: asyncio.AbstractEventLoop,
        enqueue_ui: Callable[[str, Any], None],
        disconnected_cb: Callable[[], None],
        unsolicited_block_cb: Callable[[str], None],
    ):
        self.loop = loop
        self.enqueue_ui = enqueue_ui
        self.disconnected_cb = disconnected_cb
        self.unsolicited_block_cb = unsolicited_block_cb

        self.client: Optional[BleakClient] = None
        self.rx_buffer = ""
        self.pending_future: Optional[asyncio.Future] = None
        self.pending_lock = asyncio.Lock()
        self.connected = False

    async def connect(self, address: str):
        address = address.strip()
        if not address:
            raise RuntimeError("BLE address is empty")

        client = BleakClient(address, disconnected_callback=self._on_disconnect)
        await client.connect(timeout=15.0)
        if not client.is_connected:
            raise RuntimeError("Could not connect to the device")

        await client.start_notify(CHAR_TX_UUID, self._notification_handler)
        self.client = client
        self.connected = True
        self.rx_buffer = ""
        self.enqueue_ui("transport_connected", address)

    async def disconnect(self):
        try:
            if self.client and self.client.is_connected:
                try:
                    await self.client.stop_notify(CHAR_TX_UUID)
                except Exception:
                    pass
                await self.client.disconnect()
        finally:
            self.client = None
            self.connected = False
            self.rx_buffer = ""
            if self.pending_future and not self.pending_future.done():
                self.pending_future.cancel()
            self.pending_future = None

    async def request(self, text: str, timeout_s: float = COMMAND_TIMEOUT_S) -> str:
        async with self.pending_lock:
            if not self.client or not self.client.is_connected:
                raise RuntimeError("No BLE connection")

            if self.pending_future and not self.pending_future.done():
                raise RuntimeError("Another request is already pending")

            future = self.loop.create_future()
            self.pending_future = future

            try:
                self.enqueue_ui("log", f"[TX] {text}")
                payload = text.encode("utf-8")
                for i in range(0, len(payload), BLE_WRITE_CHUNK_SIZE):
                    chunk = payload[i : i + BLE_WRITE_CHUNK_SIZE]
                    await self.client.write_gatt_char(CHAR_RX_UUID, chunk, response=False)
                    await asyncio.sleep(0.005)

                block = await asyncio.wait_for(future, timeout=timeout_s)
                return block
            finally:
                if self.pending_future is future:
                    self.pending_future = None

    def _on_disconnect(self, _client: BleakClient):
        self.connected = False
        self.client = None
        self.rx_buffer = ""
        if self.pending_future and not self.pending_future.done():
            self.pending_future.cancel()
        self.pending_future = None
        self.enqueue_ui("log", "Device disconnected")
        self.enqueue_ui("transport_disconnected", None)
        self.disconnected_cb()

    def _notification_handler(self, _sender: int, data: bytearray):
        chunk = data.decode("utf-8", errors="ignore")
        if not chunk:
            return

        self.rx_buffer += chunk
        while "@" in self.rx_buffer:
            completed, remaining = self.rx_buffer.split("@", 1)
            self.rx_buffer = remaining
            block = f"{completed}@"
            self.enqueue_ui("raw_block", block)
            if self.pending_future and not self.pending_future.done():
                self.pending_future.set_result(block)
            else:
                self.unsolicited_block_cb(block)


class MeMeAApp:
    def __init__(self, root: tk.Tk):
        self.root = root
        self.root.title("E-probe App")
        self.root.geometry("1480x940")
        self._apply_window_icon()

        self.theme = dict(THEME_COLORS)
        self.font_sizes = dict(FONT_SIZES)
        self.root.configure(bg=self.theme["main_bg"])

        self.ui_queue: "queue.Queue[Tuple[str, Any]]" = queue.Queue()
        self.closing = False
        self.connected = False
        self.live_running = False
        self.current_status = tk.StringVar(value="Disconnected")
        self.address_var = tk.StringVar(value=DEFAULT_DEVICE_ADDRESS)
        self.sample_name_var = tk.StringVar(value="Fish sample")
        self.sample_note_var = tk.StringVar(value="")
        self.command_var = tk.StringVar(value="")
        self.save_dir_var = tk.StringVar(value=CONFIG_DIR)
        self.bridge_battery_var = tk.StringVar(value="--")
        self.temperature_var = tk.StringVar(value="-- °C")
        self.force_counts_var = tk.StringVar(value="--")
        self.force_g_var = tk.StringVar(value="-- g")
        self.force_n_var = tk.StringVar(value="-- N")
        self.force_range_status_var = tk.StringVar(value="No reading")
        self.last_config_text = ""
        self.latest_sensor_snapshot: Dict[str, Optional[float]] = {}
        self.spectrum_records: List[SpectrumRecord] = []
        self.last_spectrum: Optional[SpectrumRecord] = None
        self.last_spectrum_index: Optional[int] = None
        self.last_timeseries: Optional[Dict[str, List[float]]] = None
        self.last_timeseries_timestamp: Optional[str] = None
        self.last_timeseries_freq_hz: Optional[float] = None
        self.sensor_history_t: Deque[float] = deque(maxlen=240)
        self.sensor_history_temp: Deque[float] = deque(maxlen=240)
        self.sensor_history_force_n: Deque[float] = deque(maxlen=240)
        self.sensor_sample_counter = 0
        self.session_start = datetime.now().strftime("%Y%m%d_%H%M%S")

        self.freq_var = tk.StringVar(value="1000000")
        self.avg_var = tk.StringVar(value="20")
        self.dac_var = tk.StringVar(value="4080")
        self.stimulus_var = tk.StringVar(value="1 - MLS")
        self.auto_scale_var = tk.BooleanVar(value=False)
        self.filter_window_var = tk.StringVar(value="5")
        self.ema_alpha_var = tk.StringVar(value="0.10")
        self.rtrans_var = tk.StringVar(value="7500")
        self.inst_gain_var = tk.StringVar(value="17.6")
        self.fft_min_var = tk.StringVar(value="0.01468")
        self.sine_period_var = tk.StringVar(value="10")
        self.timeseries_freq_var = tk.StringVar(value="1000")
        self.sensor_interval_ms_var = tk.StringVar(value="250")
        self.force_min_g_var = tk.StringVar(value="50")
        self.force_max_g_var = tk.StringVar(value="150")
        self.fit_status_var = tk.StringVar(value="No fit")
        self.logo_photo = None
        self.logo_label = None
        self.status_label = None

        self.loop = asyncio.new_event_loop()
        self.loop_thread = threading.Thread(target=self._run_loop, daemon=True)
        self.loop_thread.start()
        self.transport = BLETransport(
            loop=self.loop,
            enqueue_ui=self._enqueue_ui,
            disconnected_cb=self._handle_disconnected_background,
            unsolicited_block_cb=self._handle_unsolicited_block,
        )

        self._apply_theme()
        self._build_ui()
        self._update_connection_buttons()
        self._update_action_buttons()

        self.root.protocol("WM_DELETE_WINDOW", self.on_close)
        self.root.after(100, self._drain_ui_queue)

    # ---------- UI setup ----------
    def _apply_window_icon(self):
        if not os.path.isfile(APP_ICON_PATH):
            return
        try:
            self.root.iconbitmap(APP_ICON_PATH)
        except Exception:
            pass

    def _load_event_logo(self, parent):
        if not PIL_AVAILABLE:
            return
        if not os.path.isfile(EVENT_LOGO_PATH):
            return
        try:
            image = Image.open(EVENT_LOGO_PATH)
            image.thumbnail((180, 90), Image.LANCZOS)
            self.logo_photo = ImageTk.PhotoImage(image)
            self.logo_frame = tk.Frame(parent, bg="white", bd=0, highlightthickness=0)
            self.logo_frame.grid(row=0, column=9, rowspan=2, sticky="ne", padx=(16, 0), pady=(2, 2))
            self.logo_label = tk.Label(self.logo_frame, image=self.logo_photo, bg="white", bd=0, highlightthickness=0)
            self.logo_label.pack(padx=8, pady=6)
        except Exception:
            self.logo_photo = None
            self.logo_label = None
            self.logo_frame = None


    def _apply_theme(self):
        style = ttk.Style()
        try:
            style.theme_use("clam")
        except Exception:
            pass

        style.configure(".", background=self.theme["main_bg"], foreground=self.theme["text"], font=("Segoe UI", self.font_sizes["base"]))
        style.configure("TFrame", background=self.theme["main_bg"])
        style.configure("TLabel", background=self.theme["panel_bg"], foreground=self.theme["text"], font=("Segoe UI", self.font_sizes["base"]))
        style.configure("Header.TLabel", background=self.theme["main_bg"], foreground=self.theme["text"], font=("Segoe UI", self.font_sizes["base"]))
        style.configure(
            "TButton",
            background=self.theme["accent"],
            foreground="#ffffff",
            padding=8,
            borderwidth=0,
            font=("Segoe UI", self.font_sizes["button"], "bold"),
        )
        style.map(
            "TButton",
            background=[
                ("disabled", self.theme["disabled_bg"]),
                ("active", self.theme["accent_dark"]),
                ("pressed", self.theme["accent_dark"]),
            ],
            foreground=[("disabled", self.theme["disabled_text"]), ("active", "#ffffff")],
        )
        style.configure("TCheckbutton", background=self.theme["panel_bg"], foreground=self.theme["text"], font=("Segoe UI", self.font_sizes["base"]))
        style.configure("TRadiobutton", background=self.theme["panel_bg"], foreground=self.theme["text"], font=("Segoe UI", self.font_sizes["base"]))
        style.configure("TLabelframe", background=self.theme["panel_bg"], foreground=self.theme["text"], borderwidth=1)
        style.configure("TLabelframe.Label", background=self.theme["panel_bg"], foreground=self.theme["accent_dark"], font=("Segoe UI", self.font_sizes["frame_title"], "bold"))
        style.configure("TNotebook", background=self.theme["main_bg"], borderwidth=0)
        style.configure("TNotebook.Tab", background=self.theme["panel_bg"], foreground=self.theme["text"], padding=(16, 8), font=("Segoe UI", self.font_sizes["tab"], "bold"))
        style.map(
            "TNotebook.Tab",
            background=[("selected", self.theme["accent"]), ("active", self.theme["panel_bg"])],
            foreground=[("selected", "#ffffff"), ("active", self.theme["text"])],
        )
        style.configure("Treeview", background=self.theme["panel_bg"], fieldbackground=self.theme["panel_bg"], foreground=self.theme["text"])
        style.configure("Treeview", rowheight=34, background=self.theme["panel_bg"], fieldbackground=self.theme["panel_bg"], foreground=self.theme["text"], font=("Segoe UI", self.font_sizes["tree"]))
        style.configure("Treeview.Heading", background=self.theme["accent_dark"], foreground="#ffffff", font=("Segoe UI", self.font_sizes["tree"], "bold"))
        style.map("Treeview", background=[("selected", self.theme["accent"])], foreground=[("selected", "#ffffff")])
        style.configure("TEntry", fieldbackground=self.theme["entry_bg"], foreground=self.theme["text"], insertcolor=self.theme["text"], font=("Segoe UI", self.font_sizes["base"]))
